# flake8: noqa
import numpy as np
import librosa

HOP = 256

TIME_SIGNATURES = {
    "4/4":  (4, 1.0, True),
    "3/4":  (3, 1.0, True),
    "2/4":  (2, 1.0, True),
    "2/2":  (2, 2.0, True),
    "6/8":  (2, 1.5, True),     # two dotted-quarter beats
    "9/8":  (3, 1.5, True),
    "12/8": (4, 1.5, True),
    "5/4":  (5, 1.0, False),
    "7/4":  (7, 1.0, False),
    "5/8":  (5, 0.5, False),
    "7/8":  (7, 0.5, False),
}

BPM_MODES = {"Felt beat (the one you tap)": "felt", "Quarter notes (like a DAW)": "quarter"}

LEVEL_MULTS = (1 / 3, 1 / 2, 1.0, 2.0, 3.0)       # the usual metrical-level mistakes: factors of 2 and 3

ALLOWED_RATIOS = (1 / 3, 1 / 2, 2 / 3, 1.0, 3 / 2, 2.0, 3.0)

WRONG_LEVEL = ((0.28, 0.40), (0.42, 0.57), (0.57, 0.78), (1.30, 1.75), (1.75, 2.30), (2.60, 3.40))

RISE_FRAC = 0.2     # a hit "starts" where its onset curve reaches this fraction of its peak


def sig_spec(name):
    n, q, reg = TIME_SIGNATURES[name]
    return dict(name=name, beats=n, beat_q=q, regular=reg, bar_q=n * q)


def anchor_q(spec):
    """Quarter notes between two anchors (a felt beat for regular meters, a whole bar for irregular ones)."""
    return spec["bar_q"] if not spec["regular"] else spec["beat_q"]


def period_to_bpm(period, spec, mode="felt"):
    if mode == "quarter" or not spec["regular"]:       # odd meters have no single felt beat: count quarter notes
        return 60.0 * anchor_q(spec) / period
    return 60.0 / period


def bpm_to_period(bpm, spec, mode="felt"):
    if mode == "quarter" or not spec["regular"]:
        return 60.0 * anchor_q(spec) / bpm
    return 60.0 / bpm


def infer_signature(beats, down):
    """Auto mode: count the beats the tracker puts between downbeats. Returns (name, count) or None."""
    if down is None or len(down) < 6 or len(beats) < 12:
        return None
    tol = 0.3 * float(np.median(np.diff(beats)))
    counts = np.diff(np.searchsorted(beats, down - tol))
    vals, c = np.unique(counts, return_counts=True)
    m = int(vals[np.argmax(c)])
    if c.max() / len(counts) < 0.6:
        return None
    table = {2: "2/4", 3: "3/4", 4: "4/4", 5: "5/4", 6: "6/8", 7: "7/8", 8: "4/4", 9: "9/8", 12: "12/8"}
    return (table[m], m) if m in table else None


def _log_mode(values, weights, res=0.02, spread=0.06):
    """The most common value (weighted by how much of the song it covers), found on a log scale."""
    values = np.asarray(values, float); weights = np.asarray(weights, float)
    ok = values > 1e-3
    values, weights = values[ok], weights[ok]
    lv = np.log(values)
    bins = np.arange(lv.min() - 0.1, lv.max() + 0.1 + res, res)
    h, _ = np.histogram(lv, bins=bins, weights=weights)
    k = max(1, int(round(spread / res)))
    h = np.convolve(h, np.ones(2 * k + 1), mode="same")
    c = bins[int(np.argmax(h))] + res / 2
    near = np.abs(lv - c) < 0.1
    return float(np.exp(np.average(lv[near], weights=weights[near])))


def level_reference(beats, down, spec):
    """The song's own pulse period: the level that most of the song (by time) is tracked at.
    Bars vote too (bar length / beats per bar)."""
    iv = np.diff(beats)
    vals, wts = list(iv), list(iv)
    bars_ok, Lm, L_mode = False, None, None
    if down is not None and len(down) >= 6:
        L = np.diff(down)
        Lm = float(np.median(L))
        L_mode = _log_mode(L, L)                       # the bar length most of the song has (not fooled by 2-bar gaps)
        bars_ok = float(np.mean(np.abs(L / Lm - 1) < 0.18)) >= 0.6
        B = spec["beats"] if spec["regular"] else 1
        vals += list(L / B); wts += list(0.7 * L)
    return _log_mode(vals, wts), Lm, bars_ok, L_mode


def choose_level(r_det, Lm, spec, typed_T, bpm_lo, bpm_hi, log=print):
    """Pick the anchor period: r_det times a factor of 1/3, 1/2, 1, 2 or 3 (the usual level mistakes).
    A typed target BPM picks the factor closest to it - so it can never cause a 2x or 3x stretch. Without a typed
    BPM the tempo range (80-160 by default) and the bar length decide."""
    regular = spec["regular"]
    unit = spec["beat_q"] if regular else spec["bar_q"]
    if not regular and Lm is not None:
        r_det = Lm                                      # irregular meters: the anchor is the bar
    if typed_T:
        m = min(LEVEL_MULTS, key=lambda m: abs(np.log(m * r_det / typed_T)))
        if m != 1.0:
            log(f"  your target is about {m:g}x the detected beat level - counting beats at that level "
                f"instead (no extra stretching)")
        return r_det * m
    best, best_s = r_det, -1.0
    for m in LEVEL_MULTS:
        c = m * r_det
        bpm = 60.0 * unit / c
        s_ = (1.0 if bpm_lo <= bpm < bpm_hi else 0.0) - 0.03 * abs(np.log(m))      # prefer the smaller change
        if Lm is not None:
            Bn = spec["beats"] if regular else 1
            if abs(np.log(c * Bn / Lm)) < 0.12:
                s_ += 0.3
        if s_ > best_s:
            best, best_s = c, s_
    if best != r_det:
        log(f"  tempo level: using {best / r_det:g}x the detected beat spacing so the BPM falls in "
            f"{bpm_lo:g}-{bpm_hi:g}")
    return best


def _pll(b, s, r0, tol=0.28):
    """A flywheel that remembers the tempo. It walks along the detected beats from index s:
      - a beat near the expected spot is accepted (and the tempo follows it slowly);
      - beats too early are dropped (extras / a denser metrical level);
      - if nothing is near the expected spot the flywheel just carries on at the remembered tempo, so a passage with
        missed or off-level beats (half-time, a hemiola, a soft part) cannot change the tempo;
      - after coasting for a while the catch window widens, so the phase can be re-acquired (the tempo is not
        changed by a phase correction);
      - if the beats clearly settle into a steady run at about the same tempo but a different phase, it re-locks.
    Because the reference changes only slowly, a long run of wrong-level beats is corrected - which the old
    9-beat median could not do."""
    n = len(b)
    cur = float(b[s]); r = float(r0)
    out = [cur]; events = []
    i = s + 1
    coast = 0                                            # anchors placed without a beat to confirm them
    while i < n:
        exp = cur + r
        w = min(tol + 0.1 * min(coast, 2), 0.48)         # catch window (fraction of a beat)
        while i < n and b[i] < exp - w * r:
            events.append((float(b[i]), "drop")); i += 1
        if i >= n:
            break
        if b[i] <= exp + w * r:
            j, best = i, i
            while j < n and b[j] <= exp + w * r:
                if abs(b[j] - exp) < abs(b[best] - exp):
                    best = j
                j += 1
            new = float(b[best]); i = best + 1
            step = new - cur
            if w > tol + 1e-9:                           # phase correction only: leave the tempo alone
                step = r
            coast = 0
        else:
            gap = b[i] - cur
            q = gap / r
            k = max(1, int(round(q)))
            run = b[i:i + 4]
            steady = (len(run) == 4 and np.all((np.diff(run) > 0.8 * r) & (np.diff(run) < 1.25 * r)))
            if k >= 2 and (abs(q - k) <= tol or steady):  # a later grid position / a steady run: fill the gap
                new = float(b[i]); i += 1
                step = gap / k
                for m_ in range(1, k):
                    out.append(cur + step * m_); events.append((cur + step * m_, "add"))
                if steady and abs(q - k) > tol:
                    events.append((new, "relock")); step = r
                coast = 0
            elif steady:                                 # steady beats, shifted phase: re-lock
                new = float(b[i]); i += 1
                step = r
                events.append((new, "relock")); coast = 0
            else:                                        # nothing usable here: keep the flywheel turning
                new = exp; step = r
                events.append((exp, "add")); coast += 1
        r = min(max(0.7 * r + 0.3 * step, 0.7 * r0), 1.4 * r0)
        cur = new
        out.append(cur)
    return out, events


def _start_index(b, r0, down=None):
    """A good place to start: inside a steady run of beats (preferably on a downbeat)."""
    steady = []
    for i in range(len(b) - 3):
        q = np.diff(b[i:i + 4]) / r0
        if np.all((q > 0.75) & (q < 1.3)):
            steady.append(i)
    if steady:
        if down is not None:
            for i in steady[:60]:
                if np.min(np.abs(down - b[i])) < 0.2 * r0:
                    return i
        return steady[0]
    return 0


def clean_sequence(b, r0, start):
    fwd, ev1 = _pll(b, start, r0)
    if start > 0:
        bwd, ev2 = _pll(-b[:start + 1][::-1], 0, r0)
        back = [-t for t in bwd[1:]][::-1]
        return np.array(back + fwd), ev1 + [(-t, k) for t, k in ev2]
    return np.array(fwd), ev1


def summarize_events(events, r0):
    """Merge nearby corrections into (start, end, n_added, n_dropped) stretches for the log."""
    out = []
    for t, k in sorted(events):
        if out and t - out[-1][1] < 4 * r0:
            out[-1][1] = t
        else:
            out.append([t, t, 0, 0])
        if k in ("add", "drop"):
            out[-1][2 if k == "add" else 3] += 1
    return [tuple(o) for o in out if o[2] + o[3] >= 3]      # ignore one-off glitches


def _circular_period(iv, plo):
    """Typical interval, ignoring which octave (x2 / x0.5) each interval is in, folded into [plo, 2*plo).
    A half-time passage therefore votes for the same tempo as everything else instead of splitting it."""
    iv = iv[iv > 0]
    z = np.exp(2j * np.pi * np.log2(iv / plo))
    ang = np.angle(z.mean()) % (2 * np.pi)
    return float(plo * 2 ** (ang / (2 * np.pi)))


def bars_reference(beats, down, spec, typed_T, bpm_lo, bpm_hi, log=print):
    """The period the whole song should be tracked at. Returns (period, 'beat' | 'bar', bars_ok)."""
    B, bq, regular = spec["beats"], spec["beat_q"], spec["regular"]
    iv = np.diff(beats)
    m_b = float(np.median(iv))
    bars_ok, Lm = False, None
    if down is not None and len(down) >= 6:
        L = np.diff(down)
        Lm = float(np.median(L))
        bars_ok = float(np.mean(np.abs(L / Lm - 1) < 0.18)) >= 0.6
    if not regular:
        kind = "bar"
        if bars_ok:
            r0 = Lm
        else:
            r0 = B * _circular_period(iv, 60.0 * bq / bpm_hi)
            log("  no usable bar information - assuming one bar every %d beats" % B)
    else:
        kind = "beat"
        if bars_ok:
            r0 = Lm / B
            ratio = m_b / r0
            if 0.42 < ratio < 0.6 and not typed_T:       # tracker is denser than the bars suggest: eighths, or 2-bar "bars"?
                bpm_c = 60.0 * bq / r0
                if not (bpm_lo <= bpm_c < bpm_hi) and bpm_lo <= 2 * bpm_c < bpm_hi:
                    r0 = r0 / 2
                    log("  bars look 2x too long for this time signature - using the faster beat level")
        else:
            r0 = _circular_period(iv, 60.0 * bq / bpm_hi)
    if typed_T:                                          # the BPM you typed picks the octave (never a 2x stretch)
        r_typed = typed_T
        k = int(np.argmin([abs(np.log(r0 * 2.0 ** kk / r_typed)) for kk in range(-2, 3)])) - 2
        if k:
            log(f"  your target BPM is {2.0 ** abs(k):g}x {'faster' if k < 0 else 'slower'} than the detected tempo - "
                f"counting beats at that level instead (no extra stretching)")
            r0 *= 2.0 ** k
    return r0, kind, bars_ok


def anchors_from_bars(bars, B, beats, total_dur, snap=0.18):
    """Regular meters: split every (cleaned) bar into B equal beats, then snap each to a tracker beat if one is
    close. Using the bars as the skeleton means beat-level mistakes (half-time, double-time, the wrong eighth)
    cannot move the grid; the detected beats only fine-tune where they agree."""
    lens = np.diff(bars)
    Lm = float(np.median(lens))
    out, per = [], []
    for j in range(len(bars)):
        L = lens[j] if j < len(lens) else Lm
        for k in range(B):
            t = bars[j] + L * k / B
            if t < total_dur - 0.05:
                out.append(t); per.append(L / B)
    out = np.array(out); per = np.array(per)
    if len(beats):                                   # nothing to anchor on after the last detected beat
        keep = out <= beats[-1] + 0.5 * per
        out, per = out[keep], per[keep]
    match = 0.0
    if len(beats):
        idx = np.clip(np.searchsorted(beats, out), 1, len(beats) - 1)
        left, right = beats[idx - 1], beats[idx]
        near = np.where(np.abs(out - left) <= np.abs(out - right), left, right)
        ok = np.abs(near - out) <= snap * per
        match = float(np.mean(ok))
        out = np.where(ok, near, out)
    for k in range(1, len(out)):                     # keep strictly increasing
        if out[k] <= out[k - 1] + 1e-3:
            out[k] = out[k - 1] + 1e-3
    return out, match


def prepare_anchors(beats, down, total_dur, spec, typed_T=None, bpm_lo=80.0, bpm_hi=160.0, log=print):
    """Turn raw tracker output into a clean list of anchors: felt beats for regular meters, bars for irregular ones.
    Stage 1 builds the grid (from the bars when they are reliable - they hold the phase steady - otherwise by following
    the beats). Stage 2 forces every part of the song to ONE tempo level, so nothing can stay at double / half / a
    third of the tempo. Returns dict(anchors, head, tail, r0, kind, events, bars_ok)."""
    b = np.asarray(sorted(set(np.round(np.asarray(beats, float), 5))), dtype=float)
    if len(b) < 8:
        raise RuntimeError("Could not find enough beats in this file.")
    d = None
    if down is not None and len(down) >= 4:
        d = np.asarray(sorted(set(np.round(np.asarray(down, float), 5))), dtype=float)
    r_det, Lm, bars_ok, L_mode = level_reference(b, d, spec)
    events = []
    if spec["regular"] and bars_ok and d is not None:
        # ---- stage 1a: bars are the skeleton; every bar is split into the signature's beats
        r_bar, _, _ = bars_reference(b, d, spec, typed_T, bpm_lo, bpm_hi, log=lambda *a: None)
        B_ = spec["beats"]
        bars, ev = clean_sequence(d, r_bar * B_, _start_index(d, r_bar * B_))
        if len(bars) < 4:
            raise RuntimeError("Could not find enough bars in this file.")
        seq, match = anchors_from_bars(bars, B_, b, total_dur)
        if match < 0.4:
            log(f"  NOTE: only {match * 100:.0f}% of the detected beats line up with {B_} beats per bar - "
                f"is {spec['name']} the right time signature? (the bars themselves are still made even)")
        events += ev
        kind = "beat"
    elif spec["regular"]:
        # ---- stage 1b: no usable bars - follow the beats (downbeats count as beats too)
        r0 = choose_level(r_det, L_mode, spec, typed_T, bpm_lo, bpm_hi, log=lambda *a: None)
        cand = b if d is None else np.sort(np.concatenate([b, d]))
        cand = cand[np.concatenate([[True], np.diff(cand) > 0.15 * r0])]
        seq, ev = clean_sequence(cand, r0, _start_index(cand, r0, d))
        events += ev
        kind = "beat"
    else:
        kind = "bar"
        r_bar, _, _ = bars_reference(b, d, spec, typed_T, bpm_lo, bpm_hi, log)
        if bars_ok and d is not None:
            seq0 = d
        else:
            r_pulse = r_bar / spec["beats"]
            pulses, _ = clean_sequence(b, r_pulse, _start_index(b, r_pulse))
            seq0 = pulses[::spec["beats"]]
        seq, ev = clean_sequence(seq0, r_bar, _start_index(seq0, r_bar))
        events += ev
    if len(seq) < 6:
        raise RuntimeError("Could not find enough beats/bars in this file.")
    # ---- stage 2: one tempo level for the whole song
    iv = np.diff(seq)
    r_a = _log_mode(iv, iv)                                   # what most of the song's anchors are spaced at
    T = choose_level(r_a, L_mode, spec, typed_T, bpm_lo, bpm_hi, log)
    anchors, ev2 = clean_sequence(seq, T, _start_index(seq, T))
    n_fix = sum(1 for _, k in ev2 if k in ("add", "drop"))
    if n_fix >= 3:
        events += ev2
    if len(anchors) < 6:
        raise RuntimeError("Beat list collapsed during cleaning - this file may not have a clear beat.")
    iv = np.diff(anchors)
    return dict(anchors=anchors, head=float(np.median(iv[:8])), tail=float(np.median(iv[-8:])), r0=T, kind=kind,
                events=summarize_events(events, T), bars_ok=bars_ok)


def _rolling_median(x, w=5):
    h = w // 2
    p = np.pad(x, h, mode="edge")
    return np.array([np.median(p[i:i + w]) for i in range(len(x))])


def _wmedian(v, w):
    o = np.argsort(v); v, w = np.asarray(v)[o], np.asarray(w)[o]
    return float(v[np.searchsorted(np.cumsum(w), 0.5 * w.sum())])


def pick_reference_period(anchors, typed_T=None, bars_T=None, support=0.2):
    """The felt-beat spacing the song is REALLY at. Without a typed target: the time-weighted median spacing (the
    level most of the song sits at). With one: of the spacings that big parts of the song sit at, the one closest
    to the typed tempo."""
    iv = np.diff(anchors)
    sm = _rolling_median(iv, 9)
    base = _wmedian(sm, iv)
    prior = typed_T or bars_T
    if not prior:
        return base
    tot = iv.sum()
    cands = []
    for c in np.unique(np.round(sm, 2)):
        near = np.abs(np.log(sm / c)) < 0.15
        if iv[near].sum() / tot >= support:
            cands.append(_wmedian(sm[near], iv[near]))
    if not cands:
        return base
    return min(cands, key=lambda c: abs(np.log(c / prior)))


def find_bad_runs(anchors, T, min_len=4, merge_gap=10):
    iv = np.diff(anchors)
    sm = _rolling_median(iv, 9) / T
    bad = np.zeros(len(sm), bool)
    for lo, hi in WRONG_LEVEL:
        bad |= (sm >= lo) & (sm <= hi)
    runs, i = [], 0
    while i < len(bad):
        if bad[i]:
            j = i
            while j + 1 < len(bad) and bad[j + 1]:
                j += 1
            runs.append([i, j + 1])          # anchor indices i..j+1
            i = j + 1
        else:
            i += 1
    out = []
    for r in runs:
        if out and r[0] - out[-1][1] <= merge_gap:
            out[-1][1] = r[1]
        else:
            out.append(r)
    return [(a, b) for a, b in out if b - a >= min_len]


def onset_env(y, sr, hop=256):
    y_perc = librosa.effects.percussive(y, margin=2.0)
    env = librosa.onset.onset_strength(y=y_perc, sr=sr, hop_length=hop, aggregate=np.median, lag=1, max_size=3)
    full = librosa.onset.onset_strength(y=y, sr=sr, hop_length=hop)
    return env / (env.max() + 1e-9) + 0.5 * full / (full.max() + 1e-9)


def retrack_region(env, sr, hop, t_a, t_b, T, tightness=80):
    """Beats between t_a and t_b at the song's own level: Ellis dynamic programming, tempo pinned to T."""
    fa, fb = int(t_a * sr / hop), int(t_b * sr / hop) + 1
    seg = env[fa:fb]
    if len(seg) < 8:
        return None
    _, fr = librosa.beat.beat_track(onset_envelope=seg, sr=sr, hop_length=hop, bpm=60.0 / T,
                                    tightness=tightness, trim=False)
    return t_a + librosa.frames_to_time(fr, sr=sr, hop_length=hop)


def _tidy(beats, T, lo=0.7, hi=1.4):
    """After re-tracking: no gap bigger than 1.4 T (fill evenly) and no beat closer than 0.7 T (drop it)."""
    out = [beats[0]]
    for t in beats[1:]:
        gap = t - out[-1]
        if gap < lo * T:
            continue
        if gap > hi * T:
            k = int(round(gap / T))
            out.extend(out[-1] + gap * m / k for m in range(1, k))
        out.append(t)
    return np.array(out)


def enforce_level(anchors, y, sr, T_ref, log=print, hop=HOP):
    """Find stretches of anchors whose spacing is NOT the song's own level (typically 2/3, 4/3, 3/2, 1/2 or 2x of it)
    and re-track them from the audio with the tempo pinned. Returns (new anchors, [(t_start, t_end, ratio), ...])."""
    anchors = np.asarray(anchors, float)
    runs = find_bad_runs(anchors, T_ref)
    if not runs:
        return anchors, []
    env = onset_env(y, sr, hop)
    N = len(anchors)
    iv = np.diff(anchors)
    out, fixes, last = [], [], 0
    for a, b in runs:
        ia = max(a - 1, 0)
        at_end = b >= N - 2
        ib = N - 1 if at_end else b + 1
        t_a = anchors[ia]
        t_b = anchors[-1] + 0.5 * T_ref if at_end else anchors[ib]
        beats = retrack_region(env, sr, hop, t_a, t_b, T_ref)
        if beats is None:
            continue
        keep = beats[(beats > t_a + 0.5 * T_ref) & (beats < (t_b if at_end else t_b - 0.5 * T_ref))]
        if len(keep) < 3:
            continue
        seg = _tidy(np.concatenate([[t_a], keep] + ([] if at_end else [[t_b]])), T_ref)
        out.extend(anchors[last:ia]); out.extend(seg if not at_end else seg)
        last = N if at_end else ib + 1
        fixes.append((float(anchors[a]), float(anchors[min(b, N - 1)]), float(np.median(iv[a:b])) / T_ref))
    out.extend(anchors[last:])
    out = np.array(sorted(set(np.round(out, 5))))
    return out, fixes


def _window_env(y, sr, t, max_shift):
    """Fine-resolution onset envelope around time t. Returns (times, env) or None."""
    half = max_shift + 0.04
    a = int(max(0, (t - half) * sr))
    z = int(min(len(y), (t + half) * sr))
    if z - a < 1024:
        return None
    env = librosa.onset.onset_strength(y=y[a:z], sr=sr, n_fft=512, hop_length=32, lag=1, center=True, n_mels=40)
    if len(env) < 8:
        return None
    return a / sr + librosa.frames_to_time(np.arange(len(env)), sr=sr, hop_length=32), env


def _pick_peak(times, env, t, max_shift, ref, sr):
    """Where does the hit near t START? Finds the strongest clear transient near t, then walks back to where it
    begins to rise, so soft and sharp sounds (kick, snare, keys, guitar) are all measured the same way."""
    d = times - t
    win = np.abs(d) <= max_shift
    cand = np.zeros(len(env), bool)
    cand[1:-1] = (env[1:-1] >= env[:-2]) & (env[1:-1] >= env[2:])
    cand &= win & (env > 0.35 * ref) & (env >= 0.6 * env.max())
    if not cand.any():
        return None
    score = np.where(cand, env * np.exp(-0.5 * (d / (max_shift * 0.6)) ** 2), 0)
    j = int(np.argmax(score))
    level = RISE_FRAC * env[j]
    i = j
    while i > 1 and env[i - 1] > level and env[i - 1] <= env[i] * 1.001:
        i -= 1
    # interpolate the exact crossing of `level` between frames i-1 and i
    if i > 0 and env[i - 1] <= level < env[i]:
        frac = (level - env[i - 1]) / (env[i] - env[i - 1] + 1e-12)
        return float(times[i - 1] + frac * (times[i] - times[i - 1]))
    return float(times[i])


def _windows(y, sr, points, max_shift):
    wins = [_window_env(y, sr, t, max_shift) for t in points]
    peaks = [w[1].max() for w in wins if w is not None]
    ref = float(np.median(peaks)) if peaks else 0.0           # what a typical hit looks like in this song
    return wins, ref


def refine_beats(beats, y, sr, max_shift=0.045, log=print, return_mask=False):
    """Move each beat onto the nearest strong transient (within +-max_shift seconds).
    Neural trackers work at 20 ms steps; this brings the grid to the actual drum hit.
    With return_mask=True also returns which beats found a clear transient to lock onto."""
    out = beats.copy()
    mask = np.zeros(len(beats), bool)
    wins, ref = _windows(y, sr, beats, max_shift)
    n_fix = 0
    for k, (t, w) in enumerate(zip(beats, wins)):
        if w is None:
            continue
        p = _pick_peak(w[0], w[1], t, max_shift, ref, sr)
        if p is not None:
            out[k] = p
            mask[k] = True
            n_fix += 1
    out = np.maximum.accumulate(out)
    for k in range(1, len(out)):                       # keep strictly increasing
        if out[k] <= out[k - 1] + 1e-3:
            out[k] = out[k - 1] + 1e-3
    log(f"  refined {n_fix}/{len(beats)} beats onto drum hits")
    return (out, mask) if return_mask else out


def fill_weak_runs(times, mask, max_run=32):
    """Where a stretch of beats has no clear transient (soft pads, breakdowns, vinyl noise) the tracker's positions
    are mostly noise. Space those beats evenly between the nearest beats that DID lock onto a drum hit."""
    t = times.copy()
    n = len(t)
    i = 0
    while i < n:
        if mask[i]:
            i += 1
            continue
        j = i
        while j < n and not mask[j]:
            j += 1
        if i > 0 and j < n and (j - i) <= max_run:
            t[i:j] = np.linspace(t[i - 1], t[j], j - i + 2)[1:-1]
        i = j
    return t


def grid_alignment(y, sr, grid_times, max_off=0.04, tol=0.015):
    """Share of grid points that have a drum hit within `tol` seconds, and the median offset of the hits found.
    Returns (% of grid points hit, median offset ms, % of grid points with any hit nearby)."""
    wins, ref = _windows(y, sr, grid_times, max_off)
    offs = []
    for t, w in zip(grid_times, wins):
        if w is None:
            continue
        p = _pick_peak(w[0], w[1], t, max_off, ref, sr)
        if p is not None:
            offs.append(abs(p - t))
    n = len(grid_times)
    if n < 5:
        return None
    offs = np.array(offs) if offs else np.array([1.0])
    return (float(100 * np.sum(offs <= tol) / n), float(np.median(offs) * 1000), float(100 * len(offs) / n))


def measure_offset(y, sr, grid_times, max_off=0.12):
    """Constant offset between where the grid says the hits are and where they really are in `y`.
    Returns (median offset s, spread s, number of beats measured) - or None if there is no clear beat."""
    wins, ref = _windows(y, sr, grid_times, max_off)
    offs = []
    for t, w in zip(grid_times, wins):
        if w is None:
            continue
        p = _pick_peak(w[0], w[1], t, max_off, ref, sr)
        if p is not None:
            offs.append(p - t)
    if len(offs) < 20:
        return None
    offs = np.array(offs)
    q1, med, q3 = np.percentile(offs, [25, 50, 75])
    return float(med), float(q3 - q1), len(offs)


def irregularity(beats):
    iv = np.diff(beats)
    return float(np.std(iv) / np.mean(iv) * 100)


def fmt_bpm(x):
    """92.6 -> '92.6', 128.0 -> '128' (never rounds a BPM you typed to a different number)."""
    return f"{x:.2f}".rstrip("0").rstrip(".")


def stretch_report(beats, period, warn=0.20):
    """Per-beat stretch ratio and the stretches that are big enough to hurt sound quality."""
    iv = np.diff(beats)
    T = float(period)
    ratio = T / iv                                   # >1 = slowed down, <1 = sped up
    big = np.abs(ratio - 1.0) > warn
    ranges, k = [], 0
    while k < len(big):
        if big[k]:
            m = k
            while m + 1 < len(big) and big[m + 1]:
                m += 1
            if m - k + 1 >= 2:                       # ignore single-beat blips
                ranges.append((float(beats[k]), float(beats[m + 1]), float(np.median(ratio[k:m + 1]))))
            k = m + 1
        else:
            k += 1
    return dict(ratio=ratio, max_up=float(ratio.max()), max_down=float(ratio.min()),
                pct_over=float(100 * big.mean()), ranges=ranges)
